CREATE TABLE rule_device_operation_mechanic(rule_id bigint PRIMARY KEY REFERENCES rule_rule(rule_id));
CREATE TABLE rule_device_operation(rule_id bigint NOT NULL REFERENCES rule_device_operation_mechanic(rule_id),operation_code text NOT NULL CHECK(operation_code IN('use-demolition-charge','assemble-bomb','disarm-bomb','disarm-electronic-alarm','pick-electronic-lock','disable-malfunctioning-robot','similar-electronic-device','disable-mechanical-alarm','pick-mechanical-lock','similar-mechanical-device')),device_domain text NOT NULL CHECK(device_domain IN('explosive','electronic','mechanical')),skill_rule_id bigint NOT NULL REFERENCES rule_skill(rule_id),display_order smallint NOT NULL CHECK(display_order>0),PRIMARY KEY(rule_id,operation_code),UNIQUE(rule_id,display_order));
COMMENT ON TABLE rule_device_operation IS 'CE-SKILL-018 paired-source Demolitions, Electronics, and Mechanics device operations.';
